        @(posedge clk);
        reset = 0;

        // Check value after 1 cycle (should be 1)
        @(posedge clk);
        #1;
        if (q !== 10'd1) begin
            $display("ERROR: Expected q=1 after 1 cycle, got %d", q);
            errors = errors + 1;
        end

        // Test asynchronous/mid-sequence reset assertion
        @(posedge clk);
        reset = 1;
        @(posedge clk);
        #1;
        if (q !== 10'd0) begin
            $display("ERROR: Mid-sequence reset failed. Got %d", q);
            errors = errors + 1;
        end

        // Release reset and let it run towards the wrap-around boundary (999 -> 0)
        @(posedge clk);
        reset = 0;

        // Fast forward or loop through enough cycles to verify wrap around at 999
        // We know q is 0 now. It takes 999 cycles to reach 999, then 1 more to wrap to 0.
        // Let's force/simulate or count accurately. To keep simulation concise,
        // we can check a few transitions or let it run a full 1000 cycles.
        // Since 1000 cycles is fast in simulation, a bounded loop is fine.

        for (cycle_count = 0; cycle_count < 1001; cycle_count = cycle_count + 1) begin
            @(posedge clk);
        end

        // After 1001 clock edges from reset release (q was 0, then 1..1000 cycles),
        // let's inspect the exact counter value.
        // Cycle 0: q=0 (after posedge reset=0)
        // Cycle 1: q=1
        // ...
        // Cycle 999: q=999
        // Cycle 1000: q=0 (wrapped around)
        // Cycle 1001: q=1
        #1;
        if (q !== 10'd1) begin
            $display("ERROR: Wrap-around boundary test failed. Expected q=1 after 1001 active cycles, got %d", q);
            errors = errors + 1;
        end

        // Report final results
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
